             <span class="choice-text">SMS</span>
           </label>
           <label class="choice">
             <input type="radio" name="notificationPreference" value="Push Notifications">
             <span class="choice-text">Push Notifications</span>
           </label>
         </div>
       </div>

       <button type="submit">Submit</button>
       <p class="status" id="status" aria-live="polite"></p>
     </form>
   </main>

